const categoryOptions = Array.from(
  new Set(bursariesData.flatMap((bursary) => bursary.fields))
).sort((a, b) => a.localeCompare(b));

export default function BursariesScreen() {
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All Categories");
  const [sortBy, setSortBy] = useState<"Closing Date" | "Name" | "Provider">("Closing Date");

  const filteredBursaries = useMemo(() => {
    let results = [...bursariesData];
    const query = search.toLowerCase().trim();

    if (query) {
      results = results.filter((item) =>
        item.name.toLowerCase().includes(query) ||
        item.provider.toLowerCase().includes(query) ||
        item.fields.some((field) => field.toLowerCase().includes(query))
      );
    }

    if (selectedCategory !== "All Categories") {
      results = results.filter((item) =>
        item.fields.some((field) => field.toLowerCase() === selectedCategory.toLowerCase())
      );
    }

    if (sortBy === "Name") {
      results.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortBy === "Provider") {
      results.sort((a, b) => a.provider.localeCompare(b.provider));
    }

    return results;
  }, [search, selectedCategory, sortBy]);

  const changeSort = () => {
  setSortBy((current) =>
    current === "Closing Date"
      ? "Name"
      : current === "Name"
        ? "Provider"
        : "Closing Date"
  );
};

const openDetails = (item: Bursary) => {
  router.push({
    pathname: "/funding-details",
    params: {
      id: String(item.id),
      name: item.name,
      provider: item.provider,
      closingDate: item.closingDate,
      type: "Bursary",
      fields: item.fields.join("|"),
      applyLink: item.applyLink,
    },
  });
};

const formatCategory = (category: string) =>
  category.replace(/\s+BURSARIES?$/i, "").trim();

const renderBursaryCard = ({ item }: { item: Bursary }) => (
  <Pressable
    onPress={() => openDetails(item)}
    style={({ pressed }) => [styles.card, pressed && styles.cardPressed]}
  >
    <View style={styles.logoSection}>
      <View style={styles.logoBox}>
        <Ionicons name="school-outline" size={30} color={COLORS.primary} />
      </View>
    </View>

    <View style={styles.cardContent}>
      <Text style={styles.cardTitle}>{item.name}</Text>

      <Text style={styles.cardProvider} numberOfLines={2}>
        {item.provider || "Provider not specified"}
      </Text>

      <View style={styles.infoRow}>
        <Ionicons
          name="calendar-outline"
          size={17}
          color={COLORS.primary}
        />
        <Text style={[
          styles.infoText,
          item.closingDate === "Check provider website" && { color: "#F59E0B", fontWeight: "600" }
        ]}>
          Closing date: {item.closingDate || "Check provider website"}
        </Text>
      </View>
    </View>

    <View style={styles.arrowContainer}>
      <Ionicons name="chevron-forward" size={25} color={COLORS.text} />
    </View>
  </Pressable>
);

  return (
    <SafeAreaView style={styles.safeArea}>
      <View style={styles.container}>
        <View style={styles.header}>
          <Pressable onPress={() => router.back()} style={styles.backButton}>
            <Ionicons name="arrow-back" size={27} color={COLORS.text} />
          </Pressable>

          <View style={styles.headerCenter}>
            <Text style={styles.title}>Bursaries</Text>
            <Text style={styles.subtitle}>
              Find bursaries to help fund your education.
            </Text>
          </View>
          <View style={styles.headerPlaceholder} />
        </View>

        {/* Removed: Scholarships tab — Bursaries only */}

        <View style={styles.searchBox}>
          <Ionicons name="search-outline" size={23} color={COLORS.muted} />
          <TextInput
            value={search}
            onChangeText={setSearch}
            placeholder="Search by name, provider or field..."
            placeholderTextColor={COLORS.muted}
            style={styles.searchInput}
          />
          {search.length > 0 && (
            <Pressable onPress={() => setSearch("")}>
              <Ionicons name="close-circle" size={20} color={COLORS.muted} />
            </Pressable>
          )}
        </View>

        <View style={styles.filterSection}>
          <View style={styles.filterIcon}>
            <Ionicons name="options-outline" size={20} color={COLORS.text} />
          </View>
          <FlatList
            horizontal
            data={["All Categories", ...categoryOptions]}
            keyExtractor={(item, index) => `${item}-${index}`}
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.fieldList}
            renderItem={({ item }) => {
              const selected = selectedCategory === item;
              return (
                <Pressable
                  onPress={() => setSelectedCategory(item)}
                  style={[styles.filterChip, selected && styles.filterChipSelected]}
                >
                  <Text style={[styles.filterChipText, selected && styles.filterChipTextSelected]}>
                    {formatCategory(item)}
                  </Text>
                </Pressable>
              );
            }}
          />
        </View>

        <View style={styles.sortRow}>
          <Text style={styles.resultCount}>Showing {filteredBursaries.length} results</Text>
          <Pressable onPress={changeSort} style={styles.sortButton}>
            <Text style={styles.sortText}>Sort: {sortBy}</Text>
            <Ionicons name="chevron-down" size={18} color={COLORS.text} />
          </Pressable>
        </View>

        <FlatList
          data={filteredBursaries}
          keyExtractor={(item) => String(item.id)}
          renderItem={renderBursaryCard}
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.cardsList}
          ListEmptyComponent={
            <View style={styles.emptyState}>
              <Ionicons name="search-outline" size={50} color={COLORS.muted} />
              <Text style={styles.emptyTitle}>No bursaries found</Text>
              <Text style={styles.emptyText}>Try changing your search or category filter.</Text>
            </View>
          }
        />
      </View>

      <SpeakButton text={
        "Bursaries. Find bursaries and financial aid to help fund your education. " +
        `Showing ${filteredBursaries.length} bursaries. ` +
        "Use the search bar to search by name, provider or field of study. " +
        "Tap any bursary card to view details and apply."
      } />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safeArea: { flex: 1, backgroundColor: COLORS.background },
  container: { flex: 1, backgroundColor: COLORS.background },
  header: { flexDirection: "row", alignItems: "flex-start", paddingHorizontal: 18, paddingTop: 10, paddingBottom: 18 },
  backButton: { width: 40, height: 40, justifyContent: "center", alignItems: "flex-start" },
  headerCenter: { flex: 1, alignItems: "center", paddingHorizontal: 5 },
  headerPlaceholder: { width: 40 },
  title: { fontSize: 25, fontWeight: "800", color: COLORS.text, textAlign: "center" },
  subtitle: { marginTop: 7, fontSize: 15, lineHeight: 21, color: COLORS.secondaryText, textAlign: "center" },
  typeTabs: { flexDirection: "row", gap: 8, marginHorizontal: 18, marginBottom: 16 },
  typeTab: { flex: 1, height: 54, borderRadius: 11, borderWidth: 1.5, borderColor: COLORS.primaryBorder, backgroundColor: COLORS.white, justifyContent: "center", alignItems: "center" },
  typeTabActive: { backgroundColor: COLORS.primary, borderColor: COLORS.primary },
  typeTabText: { fontSize: 16, fontWeight: "700", color: COLORS.primary },
  typeTabTextActive: { color: COLORS.white },
  searchBox: { height: 58, marginHorizontal: 18, borderRadius: 15, backgroundColor: COLORS.white, borderWidth: 1, borderColor: COLORS.border, flexDirection: "row", alignItems: "center", paddingHorizontal: 16, shadowColor: "#000", shadowOpacity: 0.05, shadowRadius: 8, shadowOffset: { width: 0, height: 2 }, elevation: 2 },
  searchInput: { flex: 1, marginLeft: 10, fontSize: 15, color: COLORS.text },
  filterSection: { flexDirection: "row", alignItems: "center", marginTop: 14, paddingLeft: 18 },
  filterIcon: { width: 40, height: 40, borderRadius: 10, backgroundColor: COLORS.white, borderWidth: 1, borderColor: COLORS.border, alignItems: "center", justifyContent: "center", marginRight: 8 },
  fieldList: { gap: 8, paddingRight: 18 },
  filterChip: { height: 40, paddingHorizontal: 14, borderRadius: 10, backgroundColor: COLORS.white, borderWidth: 1, borderColor: COLORS.border, justifyContent: "center" },
  filterChipSelected: { backgroundColor: COLORS.primaryLight, borderColor: COLORS.primary },
  filterChipText: { fontSize: 13, fontWeight: "600", color: COLORS.text },
  filterChipTextSelected: { color: COLORS.primary },
  sortRow: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 18, paddingTop: 16, paddingBottom: 10 },
  resultCount: { fontSize: 13, color: COLORS.muted, fontWeight: "600", flex: 1 },
  sortButton: { flexDirection: "row", alignItems: "center", gap: 4 },
  sortText: { fontSize: 14, fontWeight: "600", color: COLORS.text },
  cardsList: { paddingHorizontal: 18, paddingBottom: 30, gap: 14 },
  card: { flexDirection: "row", backgroundColor: COLORS.white, borderRadius: 17, borderWidth: 1, borderColor: COLORS.border, padding: 14, minHeight: 145, shadowColor: "#000", shadowOpacity: 0.06, shadowRadius: 8, shadowOffset: { width: 0, height: 3 }, elevation: 2 },
  cardPressed: { opacity: 0.85 },
  logoSection: { width: 60, alignItems: "center", paddingTop: 3 },
  logoBox: { width: 52, height: 52, borderRadius: 14, backgroundColor: COLORS.primaryLight, alignItems: "center", justifyContent: "center" },
  cardContent: { flex: 1, paddingHorizontal: 7 },
  cardTitle: { fontSize: 16, fontWeight: "800", color: COLORS.text, lineHeight: 21 },
  cardProvider: { fontSize: 13, color: COLORS.secondaryText, marginTop: 3, marginBottom: 8 },
  infoRow: { flexDirection: "row", alignItems: "center", marginBottom: 7 },
  infoText: { marginLeft: 7, fontSize: 13, color: COLORS.primary, fontWeight: "600", flexShrink: 1 },
  tagsContainer: { flexDirection: "row", flexWrap: "wrap", gap: 5, marginTop: 3 },
  fieldTag: { backgroundColor: COLORS.greenBackground, paddingHorizontal: 9, paddingVertical: 5, borderRadius: 8 },
  fieldTagText: { fontSize: 10, fontWeight: "700", color: COLORS.greenText },
  arrowContainer: { justifyContent: "center", marginLeft: 2 },
  emptyState: { alignItems: "center", paddingTop: 70 },
  emptyTitle: { marginTop: 14, fontSize: 18, fontWeight: "800", color: COLORS.text },
  emptyText: { marginTop: 6, fontSize: 14, color: COLORS.muted, textAlign: "center" },
});